        "km": "ដោយបង្កើតគណនីគ្រូរបស់ខ្ញុំ ខ្ញុំយល់ព្រមលក្ខខណ្ឌនៃសេវា និងការដំណើរការទិន្នន័យផ្ទាល់ខ្លួនរបស់ខ្ញុំដូចបានពិពណ៌នានៅក្នុងសេចក្តីជូនដំណឹងការពារទិន្នន័យ។",
        "lv": "Izveidojot savu skolotāja kontu, es piekrītu pakalpojumu sniegšanas noteikumiem un savu personas datu apstrādei, kā aprakstīts Paziņojumā par datu aizsardzību.",
        "nl": "Door mijn docentenaccount aan te maken, ga ik akkoord met de Servicevoorwaarden en de verwerking van mijn persoonlijke gegevens zoals beschreven in de Gegevensbeschermingsverklaring.",
        "pl": "Tworząc konto nauczyciela, zgadzam się z Regulaminem oraz przetwarzaniem moich danych osobowych opisanym w Informacji o ochronie danych.",
